         selfInjectingImpl.selfInvokePublicMethodPublicParamsProtectedReturnType(10);
         Assert.assertEquals("_selfInvokePublicMethodPublicParamsProtectedReturnType", SelfInterceptor.INTERCEPTED_METHOD_NAME);
     }

